class Solution:
    def commonChars(self, words: list[str]) -> list[str]:
        common = sorted(words[0])
        for word in words[1:]:
            chars, merged = sorted(word), []
            i = j = 0
            while i < len(common) and j < len(chars):
                if common[i] < chars[j]:
                    i += 1
                elif chars[j] < common[i]:
                    j += 1
                else:
                    merged.append(common[i])
                    i += 1
                    j += 1
            common = merged
        return common
